static u32 *C(int i) { return (u32 *)&t + TGO[i]; }
static u32 mix(u32 a, u32 b, int p) { int r = (a >> 16 & 255) * (100 - p) / 100 + (b >> 16 & 255) * p / 100, g = (a >> 8 & 255) * (100 - p) / 100 + (b >> 8 & 255) * p / 100, l = (a & 255) * (100 - p) / 100 + (b & 255) * p / 100; return r << 16 | g << 8 | l; }
static void apply(void) { t.ui_acc = t.acc; t.ui_acc2 = mix(t.acc, 0xFFFFFF, 80); z_theme_set(&t); z_theme_get(&t); TH = t; }
static void preset(int i) { const pre_t *p = &PR[i]; t.acc = p->acc; t.inact = p->inact; t.d1 = p->d1; t.d2 = p->d2; t.panel1 = p->p1; t.panel2 = p->p2; t.ui_bg = p->bg; t.ui_panel = p->panel; t.ui_line = p->line; t.ui_text = p->text; t.ui_muted = mix(p->text, p->bg, 45); t.ui_white = 0xFFFFFF; t.border = 0x111827; t.ttxt = 0xFFFFFF; t.ttxt2 = 0xC8CDD6; t.close = 0xC0392B; }
