static const op_t OP[] = {{"Texto", O(text_sc), 2, {"Normal", "Grande"}, 1}, {"Títulos", O(title_sc), 2, {"Normal", "Grande"}, 1}, {"Panel", O(panel_top), 2, {"Abajo", "Arriba"}, 0}, {"Menú", O(menu_grid), 2, {"Lista", "Cuadrícula"}, 0}, {"Iconos", O(icon_sc), 3, {"Chicos", "Medios", "Grandes"}, 0}, {"Ver iconos", O(show_icons), 2, {"No", "Sí"}, 0}, {"Adorno", O(motif), 2, {"No", "Sí"}, 0}};
