static void d_apar(void) { hdr("Apariencia"); for (int i = 0; i < 6; i++) { int y = 56 + i * 30; g_round(W, X0, y, 150, 26, 4, PR[i].d2); g_rect(W, X0 + 4, y + 4, 18, 18, PR[i].acc); g_text(W, X0 + 30, y + 5, _(PR[i].n), 0xFFFFFF); } for (int i = 0; i < NT; i++) { int y = 56 + i * 24; if (i == csel) g_rect(W, AX2 - 4, y, 266, 22, UI_ACC2); g_rect(W, AX2, y + 2, 26, 18, *C(i)); g_frame(W, AX2, y + 2, 26, 18, UI_LINE); g_text(W, AX2 + 34, y + 3, _(TGN[i]), UI_TEXT); } for (int i = 0; i < 24; i++) { int x = AX2 + (i % 8) * 32, y = 262 + (i / 8) * 28; g_rect(W, x, y, 28, 24, PAL[i]); g_frame(W, x, y, 28, 24, PAL[i] == *C(csel) ? UI_TEXT : UI_LINE); } u32 c = *C(csel); static const char *RG[] = {"R", "G", "B"}; for (int k = 0; k < 3; k++) { int y = 352 + k * 26, v = c >> (16 - k * 8) & 255; g_text(W, AX2, y + 2, RG[k], UI_TEXT); g_rect(W, AX2 + 18, y + 7, 200, 6, UI_LINE); g_rect(W, AX2 + 18, y + 7, v * 200 / 255, 6, k == 0 ? 0xDC2626 : k == 1 ? 0x16A34A : 0x2563EB); g_circle(W, AX2 + 18 + v * 200 / 255, y + 10, 6, UI_TEXT, 1); char n[8]; snprintf(n, 8, "%d", v); g_text(W, AX2 + 228, y + 2, n, UI_MUTED); } for (int i = 0; i < NOP; i++) { const op_t *o = &OP[i]; int y = 56 + i * 44, v = ((u32 *)&t)[o->f] - o->base; g_text(W, AX3, y, _(o->n), UI_MUTED); for (int k = 0; k < o->cnt; k++) ui_button(W, AX3 + k * 92, y + 16, 88, 24, o->o[k], v == k ? 2 : 0); } ui_button(W, W->w - 112, W->h - 40, 100, 30, "Guardar", 2); ui_button(W, W->w - 236, W->h - 40, 118, 30, "Restablecer", 0); }
static int drag = -1;
static void k_apar(zevent *e) { if (e->type == EV_UP) { drag = -1; return; } if (e->type == EV_MOVE && drag >= 0) { int v = MAX(0, MIN((e->x - AX2 - 18) * 255 / 200, 255)), sh = 16 - drag * 8; *C(csel) = (*C(csel) & ~(255u << sh)) | (u32)v << sh; apply(); return; } if (e->type != EV_DOWN) return; if (in(W->w - 112, W->h - 40, 100, 30, e)) { int r = z_theme_save(&t); snprintf(msg, 120, "%s", r ? z_errstr(r) : _("Tema guardado")); char m[60]; snprintf(m, 60, "[prueba] tema guardado: %s", r ? "error" : "OK"); z_log(m); return; } if (in(W->w - 236, W->h - 40, 118, 30, e)) { preset(0); t.title_sc = t.text_sc = 1; t.panel_top = t.menu_grid = 0; t.icon_sc = 1; t.show_icons = t.motif = 1; apply(); return; } if (e->x < AX2 - 8) { if (e->y >= 56 && e->y < 236) { preset((e->y - 56) / 30); apply(); } } else if (e->x < AX3 - 8) { if (e->y >= 56 && e->y < 56 + NT * 24) csel = (e->y - 56) / 24; else if (e->y >= 262 && e->y < 346) { int c = (e->x - AX2) / 32, r = (e->y - 262) / 28, i = r * 8 + c; if (c >= 0 && c < 8 && i < 24) { *C(csel) = PAL[i]; apply(); } } else if (e->y >= 352 && e->y < 430) { drag = (e->y - 352) / 26; int v = MAX(0, MIN((e->x - AX2 - 18) * 255 / 200, 255)), sh = 16 - drag * 8; *C(csel) = (*C(csel) & ~(255u << sh)) | (u32)v << sh; apply(); } } else { int i = (e->y - 56) / 44; if (e->y >= 56 && i < NOP && (e->y - 56) % 44 >= 16) { int k = (e->x - AX3) / 92; if (k >= 0 && k < OP[i].cnt) { ((u32 *)&t)[OP[i].f] = k + OP[i].base; apply(); } } } }
/* ---------- Fondo ---------- */
static char FP[40][160]; static int nfp, fmode, ftop; static u32 *thumb; static int tw_, th_; static char cur_f[160];
static void scanimg(const char *p, int d) { zdirent e; char q[200]; for (int i = 0; nfp < 40 && !z_readdir(p, i, &e); i++) { if (e.name[0] == '.') continue; snprintf(q, 200, "%s/%s", p, e.name); if (e.is_dir) { if (d < 3) scanimg(q, d + 1); } else if (z_ends(e.name, ".png") || z_ends(e.name, ".jpg") || z_ends(e.name, ".jpeg") || z_ends(e.name, ".bmp") || z_ends(e.name, ".gif")) strncpy0(FP[nfp++], q, 160); } }
static void f_load(void) { nfp = 0; strcpy(FP[nfp++], ""); scanimg("/rd/res", 0); zdirent d; if (!z_stat("/sys", &d)) scanimg("/sys", 0); z_cfg_gets("fondo", cur_f, 160); fmode = z_cfg_get("fondo_modo", 0); free(thumb); thumb = 0; if (cur_f[0]) { u32 *im; int w, h; if (!z_img_load(cur_f, &im, &w, &h)) { tw_ = 240; th_ = 150; thumb = malloc(tw_ * th_ * 4); for (int y = 0; y < th_; y++) for (int x = 0; x < tw_; x++) thumb[y * tw_ + x] = im[(y * h / th_) * w + x * w / tw_]; free(im); } } }
static const char *FM[] = {"Rellenar", "Ajustar", "Centrar", "Mosaico", "Estirar"};
static void d_fondo(void) { hdr("Fondo de escritorio"); if (thumb) g_image(W, X0, 56, tw_, th_, thumb); else g_grad(W, X0, 56, 240, 150, TH.d1, TH.d2); g_frame(W, X0, 56, 240, 150, UI_LINE); g_text(W, X0, 214, _("Modo"), UI_MUTED); for (int i = 0; i < 5; i++) ui_button(W, X0 + (i % 3) * 82, 232 + (i / 3) * 30, 78, 26, FM[i], fmode == i ? 2 : 0); ui_button(W, X0, 300, 240, 28, "Otra imagen...", 0); int x = X0 + 260, vis = (W->h - 70) / 24; for (int i = ftop; i < nfp && i < ftop + vis; i++) { int y = 56 + (i - ftop) * 24; if (!strcmp(FP[i], cur_f)) g_rect(W, x, y, W->w - x - 12, 24, UI_ACC2); const char *n = FP[i][0] ? FP[i] : _("Sin imagen (degradado del tema)"); zw_clip(W, x, y, W->w - x - 12, 24); g_text(W, x + 6, y + 4, n, UI_TEXT); zw_noclip(W); } }
static void set_fondo(const char *p) { z_cfg_sets("fondo", p); z_notify(); f_load(); }
static void k_fondo(zevent *e) { if (e->type == EV_WHEEL) { ftop = MAX(0, MIN(ftop - (int)e->key * 3, nfp - 1)); return; } if (e->type != EV_DOWN) return; int x = X0 + 260; if (e->x >= x && e->y >= 56) { int i = ftop + (e->y - 56) / 24; if (i < nfp) set_fondo(FP[i]); } else if (e->y >= 232 && e->y < 288 && e->x < X0 + 246) { int i = (e->y - 232) / 30 * 3 + (e->x - X0) / 82; if (i < 5) { fmode = i; z_cfg_set("fondo_modo", i); z_notify(); } } else if (in(X0, 300, 240, 28, e)) { char p[160]; strcpy(p, cur_f[0] ? cur_f : "/sys/"); if (ui_prompt("Fondo de escritorio", "Ruta de la imagen (PNG, JPEG, BMP o GIF):", p, 150)) { u32 *im; int w, h; if (z_img_load(p, &im, &w, &h)) strcpy(msg, _("No se puede abrir la imagen")); else { free(im); set_fondo(p); } } } }
/* ---------- Fecha y hora ---------- */
static char dbuf[16], hbuf[16]; static int dcur, hcur, dfoc;
static const char *DF[] = {"Sin fecha", "Numérica", "Día y mes", "ISO 8601", "Con día de la semana"};
static void d_fecha(void) { hdr("Fecha y hora"); u32 now[6]; z_time(now); int h24 = z_cfg_get("reloj24", 1), sg = z_cfg_get("segundos", 0), df = z_cfg_get("fecha", 1); char a[40], b[40]; z_fmt_time(now, h24, 1, a, 40); z_fmt_date(now, 4, b, 40); g_text2(W, X0, 56, a, UI_ACC, 3); g_text(W, X0, 110, b, UI_TEXT); g_text(W, X0, 140, _("Reloj"), UI_MUTED); ui_button(W, X0, 158, 110, 26, "24 horas", h24 ? 2 : 0); ui_button(W, X0 + 116, 158, 110, 26, "12 horas", h24 ? 0 : 2); ui_button(W, X0 + 240, 158, 130, 26, sg ? "Con segundos" : "Sin segundos", sg ? 2 : 0); g_text(W, X0, 196, _("Fecha en la barra"), UI_MUTED); for (int i = 0; i < 5; i++) { char p[40]; z_fmt_date(now, i, p, 40); char l[80]; snprintf(l, 80, "%s  %s", _(DF[i]), p); ui_button(W, X0, 214 + i * 30, 360, 26, l, df == i ? 2 : 0); } g_text(W, X0, 374, _("Cambiar la hora del equipo"), UI_MUTED); g_text(W, X0, 398, _(TH.lang ? "Fecha (mm/dd/aaaa)" : "Fecha (dd/mm/aaaa)"), UI_TEXT); ui_input(W, X0 + 170, 394, 120, 24, dbuf, dcur, dfoc == 1); g_text(W, X0, 428, _("Hora (hh:mm)"), UI_TEXT); ui_input(W, X0 + 170, 424, 120, 24, hbuf, hcur, dfoc == 2); ui_button(W, X0 + 300, 408, 100, 28, "Aplicar", 2); }
static void f_init(void) { u32 n[6]; z_time(n); if (TH.lang) snprintf(dbuf, 16, "%02u/%02u/%u", n[4], n[3], n[5]); else snprintf(dbuf, 16, "%02u/%02u/%u", n[3], n[4], n[5]); snprintf(hbuf, 16, "%02u:%02u", n[2], n[1]); dcur = strlen(dbuf); hcur = strlen(hbuf); }
static void k_fecha(zevent *e) { if (e->type == EV_KEY && dfoc) { if (e->ch == '\n') dfoc = 0; else if (dfoc == 1) ui_input_key(dbuf, 12, &dcur, e); else ui_input_key(hbuf, 8, &hcur, e); return; } if (e->type != EV_DOWN) return; dfoc = 0; if (in(X0, 158, 110, 26, e)) { z_cfg_set("reloj24", 1); z_notify(); } else if (in(X0 + 116, 158, 110, 26, e)) { z_cfg_set("reloj24", 0); z_notify(); } else if (in(X0 + 240, 158, 130, 26, e)) { z_cfg_set("segundos", !z_cfg_get("segundos", 0)); z_notify(); } else if (e->x < X0 + 360 && e->y >= 214 && e->y < 364) { z_cfg_set("fecha", (e->y - 214) / 30); z_notify(); } else if (in(X0 + 170, 394, 120, 24, e)) dfoc = 1; else if (in(X0 + 170, 424, 120, 24, e)) dfoc = 2; else if (in(X0 + 300, 408, 100, 28, e)) { int a = atoi(dbuf), b = atoi(dbuf + 3), y = atoi(dbuf + 6), h = atoi(hbuf), mi = atoi(hbuf + 3); int d = TH.lang ? b : a, m = TH.lang ? a : b; if (d < 1 || d > 31 || m < 1 || m > 12 || y < 2000 || y > 2099 || h > 23 || mi > 59) strcpy(msg, _("Fecha u hora no válida")); else { u32 n[6] = {0, (u32)mi, (u32)h, (u32)d, (u32)m, (u32)y}; z_rtc_set(n); strcpy(msg, _("Hora cambiada")); z_log("[prueba] hora cambiada"); z_notify(); } } }
