static void d_idioma(void) { hdr("Idioma y teclado"); g_text(W, X0, 56, _("Idioma del sistema"), UI_MUTED); for (int l = 0; l < 2; l++) { int x = X0 + l * 220; g_round(W, x, 76, 210, 70, 8, TH.lang == l ? UI_ACC2 : UI_WHITE); g_frame(W, x, 76, 210, 70, TH.lang == l ? UI_ACC : UI_LINE); z_flag(W, x + 14, 101, l); g_textb(W, x + 56, 102, l ? "English (US)" : "Español", UI_TEXT); } g_text(W, X0, 160, _("También puedes cambiarlo con la bandera del panel."), UI_MUTED); zsys s; z_sysinfo(&s); g_text(W, X0, 200, _("Distribución del teclado"), UI_MUTED); ui_button(W, X0, 220, 150, 28, "Español", s.layout ? 2 : 0); ui_button(W, X0 + 160, 220, 150, 28, "Inglés (EE. UU.)", s.layout ? 0 : 2); g_text(W, X0, 266, _("Bloq Num y Bloq Mayús se activan con sus teclas; las luces del teclado se actualizan."), UI_MUTED); }
static void k_idioma(zevent *e) { if (e->type != EV_DOWN) return; for (int l = 0; l < 2; l++) if (in(X0 + l * 220, 76, 210, 70, e)) { ztheme t2; z_theme_get(&t2); t2.lang = l; z_theme_set(&t2); z_cfg_set("idioma", l); char m[40]; snprintf(m, 40, "[prueba] idioma %d", l); z_log(m); } if (in(X0, 220, 150, 28, e)) { z_setlayout(1); z_cfg_set("teclado", 1); } else if (in(X0 + 160, 220, 150, 28, e)) { z_setlayout(0); z_cfg_set("teclado", 0); } }
