static u32 jb; static int jx, jy, wiz = -1;
static const char *JN[] = {"A", "B", "X", "Y", "Select", "Start", "L", "R"}; static const char *JK[] = {"mando_a", "mando_b", "mando_x", "mando_y", "mando_select", "mando_start", "mando_l", "mando_r"}; static const int JD[] = {0, 1, 2, 3, 8, 9, 4, 5}; static const char *JA[] = {"Espacio: disparar, saltar", "Intro: aceptar", "Flecha arriba: girar", "Tecla X", "Esc: salir", "P: pausa", "Re Pág", "Av Pág"};
static void d_mando(void) { hdr("Mandos de juego"); g_text(W, X0, 56, _("Conecta un mando USB y pulsa sus botones: aquí se ve lo que llega."), UI_MUTED); int cx = X0 + 60, cy = 130; g_rect(W, cx - 12, cy - 36, 24, 72, jy < 0 || jy > 0 ? UI_LINE : UI_PANEL); g_rect(W, cx - 36, cy - 12, 72, 24, UI_PANEL); if (jx) g_rect(W, cx + (jx < 0 ? -36 : 12), cy - 12, 24, 24, UI_ACC); if (jy) g_rect(W, cx - 12, cy + (jy < 0 ? -36 : 12), 24, 24, UI_ACC); for (int i = 0; i < 16; i++) { int x = X0 + 150 + (i % 8) * 34, y = 100 + (i / 8) * 34; g_circle(W, x, y, 13, jb >> i & 1 ? UI_ACC : UI_PANEL, 1); char n[4]; snprintf(n, 4, "%d", i + 1); g_text(W, x - g_textw(n) / 2, y - 8, n, jb >> i & 1 ? 0xFFFFFF : UI_TEXT); } Y = 200; for (int i = 0; i < 8; i++) { char b[120]; snprintf(b, 120, "%-7s -> %s %d   (%s)", JN[i], _("botón"), z_cfg_get(JK[i], JD[i]) + 1, _(JA[i])); g_text(W, X0, Y, b, wiz == i ? UI_ACC : UI_TEXT); Y += 22; } if (wiz >= 0) { char b[80]; snprintf(b, 80, _("Pulsa el botón %s del mando..."), JN[wiz]); g_textb(W, X0, Y + 10, b, 0xB45309); } ui_button(W, X0, W->h - 46, 150, 30, "Configurar", 2); ui_button(W, X0 + 160, W->h - 46, 150, 30, "Restablecer", 0); }
static void k_mando(zevent *e) { if (e->type == EV_JOY) { { char m[80]; snprintf(m, 80, "[prueba] mando: botones %x x %d y %d", e->btn, e->x, e->y); z_log(m); } u32 nb = e->btn & ~jb; jb = e->btn; jx = e->x; jy = e->y; if (wiz >= 0 && nb) { int b = 0; while (!(nb >> b & 1)) b++; z_cfg_set(JK[wiz], b); wiz++; if (wiz == 8) { wiz = -1; strcpy(msg, _("Mando configurado")); z_log("[prueba] mando configurado"); } } return; } if (e->type != EV_DOWN) return; if (in(X0, W->h - 46, 150, 30, e)) wiz = 0; else if (in(X0 + 160, W->h - 46, 150, 30, e)) { for (int i = 0; i < 8; i++) z_cfg_set(JK[i], JD[i]); wiz = -1; } }
