static void p_load(void) { nwa = 0; zdirent d; for (int i = 0; nwa < 60 && !z_readdir("/sys/PROGRAMAS", i, &d); i++) if (z_ends(d.name, ".html") || z_ends(d.name, ".htm")) strncpy0(WA[nwa++], d.name, 120); }
static void d_prog(void) { hdr("Desinstalar programas"); g_text(W, X0, 50, _("Las apps web instaladas se desinstalan (van a la papelera). Los programas del sistema solo se ocultan del menú."), UI_MUTED); int vis = (W->h - 90) / 26, n = z_napps + nwa; for (int i = ptop; i < n && i < ptop + vis; i++) { int y = 74 + (i - ptop) * 26; if (i < z_napps) { const zapp *a = &z_apps[i]; g_rect(W, X0, y + 4, 16, 16, a->col); g_text(W, X0 + 24, y + 4, _(a->name), UI_TEXT); int hd = z_hidden(a->bin); g_text(W, X0 + 240, y + 4, hd ? _("oculto") : _("visible"), hd ? 0xB45309 : UI_MUTED); ui_button(W, X0 + 340, y + 1, 110, 24, hd ? "Mostrar" : "Ocultar", 0); } else { char *nm = WA[i - z_napps]; g_rect(W, X0, y + 4, 16, 16, 0x6D28D9); zw_clip(W, X0 + 24, y, 300, 26); g_text(W, X0 + 24, y + 4, nm, UI_TEXT); zw_noclip(W); g_text(W, X0 + 340 - 0, y + 4, "", 0); ui_button(W, X0 + 340, y + 1, 110, 24, "Desinstalar", 0); } } }
static void k_prog(zevent *e) { if (e->type == EV_WHEEL) { ptop = MAX(0, ptop - (int)e->key * 3); return; } if (e->type != EV_DOWN || e->x < X0 + 340 || e->x >= X0 + 450 || e->y < 74) return; int i = ptop + (e->y - 74) / 26; if (i < z_napps) { z_set_hidden(z_apps[i].bin, !z_hidden(z_apps[i].bin)); z_notify(); } else if (i < z_napps + nwa) { char q[200]; snprintf(q, 200, _("Desinstalar %.100s? Irá a la papelera."), WA[i - z_napps]); if (ui_confirm("Desinstalar", q)) { char p[200]; snprintf(p, 200, "/sys/PROGRAMAS/%s", WA[i - z_napps]); int r = z_trash(p); snprintf(msg, 120, "%s", r ? z_errstr(r) : _("Programa desinstalado")); z_log(r ? "[prueba] desinstalar fallo" : "[prueba] desinstalado"); p_load(); } } }
/* ---------- Pantalla y sonido ---------- */
static int sdrag = -1;
static void d_pant(void) { hdr("Pantalla y sonido"); zsys s; z_sysinfo(&s); int br = z_bright_get(), vo = z_audio_vol(-1); char b[80]; for (int k = 0; k < 2; k++) { int y = 70 + k * 70, v = k ? vo : br & 255; snprintf(b, 80, "%s  %d%%%s", k ? _("Volumen") : _("Brillo"), v, !k ? (br & 256 ? _("  (hardware)") : _("  (software)")) : ""); g_text(W, X0, y, b, UI_TEXT); g_rect(W, X0, y + 26, 360, 8, UI_LINE); g_rect(W, X0, y + 26, 360 * v / 100, 8, UI_ACC); g_circle(W, X0 + 360 * v / 100, y + 30, 9, UI_ACC, 1); } snprintf(b, 80, _("Resolución: %u x %u"), s.scr_w, s.scr_h); Y = 230; ln("%s", b); char c[64]; z_audio_info(c, 64); ln("%s: %s", _("Sonido"), c); }
static void k_pant(zevent *e) { if (e->type == EV_UP) { if (sdrag >= 0) { z_cfg_set(sdrag ? "volumen" : "brillo", sdrag ? z_audio_vol(-1) : z_bright_get() & 255); z_notify(); } sdrag = -1; return; } if (e->type == EV_DOWN) { for (int k = 0; k < 2; k++) if (e->y >= 70 + k * 70 + 16 && e->y < 70 + k * 70 + 44 && e->x >= X0 - 10 && e->x < X0 + 370) sdrag = k; } if ((e->type == EV_DOWN || e->type == EV_MOVE) && sdrag >= 0) { int v = MAX(0, MIN((e->x - X0) * 100 / 360, 100)); if (sdrag) z_audio_vol(v); else z_bright_set(MAX(5, v)); } }
/* ---------- Energia y bloqueo: tiempos sin usar el equipo (los aplica el escritorio) ---------- */
typedef struct { const char *n, *key; int def; const char *unit; int nv; int v[10]; } en_t;
static const en_t EN[] = {{"Salvapantallas", "salvapantallas", 10, "min", 9, {0, 1, 2, 5, 10, 15, 20, 30, 60}}, {"Apagar la pantalla", "pantalla_off", 20, "min", 9, {0, 5, 10, 15, 20, 30, 45, 60, 120}},
    {"Suspender", "suspender", 60, "min", 7, {0, 15, 30, 45, 60, 120, 180}}, {"Apagar el equipo", "apagar_h", 4, "h", 6, {0, 1, 2, 4, 8, 12}}};
#define NEN 4
static void d_ener(void) { hdr("Energía y bloqueo"); char b[120];
    for (int i = 0; i < NEN; i++) { int y = 70 + i * 44, v = z_cfg_get(EN[i].key, EN[i].def); g_text(W, X0, y, _(EN[i].n), UI_TEXT); if (v) snprintf(b, 120, _("tras %d %s"), v, EN[i].unit); else snprintf(b, 120, "%s", _("nunca")); g_text(W, X0 + 230, y, b, UI_TEXT); g_round(W, X0 + 360, y - 4, 28, 24, 4, UI_LINE); g_text(W, X0 + 370, y, "-", UI_TEXT); g_round(W, X0 + 396, y - 4, 28, 24, 4, UI_LINE); g_text(W, X0 + 406, y, "+", UI_TEXT); }
    int pin = z_cfg_get("pin_al_volver", 1), y = 70 + NEN * 44; g_frame(W, X0, y - 2, 18, 18, UI_TEXT); if (pin) g_rect(W, X0 + 4, y + 2, 10, 10, UI_ACC); g_text(W, X0 + 28, y, _("Pedir el PIN al volver del salvapantallas"), UI_TEXT);
    y += 44; g_round(W, X0, y - 6, 240, 30, 5, UI_ACC); g_text(W, X0 + 14, y + 1, _("Probar el salvapantallas"), 0xFFFFFF);
    Y = y + 46; ln("%s", _("Suspender necesita que el equipo lo admita; si no, no hace nada.")); ln("%s", _("Antes de apagar se guardan los ajustes; guarda tus documentos.")); }
static void k_ener(zevent *e) { if (e->type != EV_DOWN) return;
    for (int i = 0; i < NEN; i++) { int y = 70 + i * 44; if (e->y < y - 4 || e->y >= y + 20) continue; int d = in(X0 + 360, y - 4, 28, 24, e) ? -1 : in(X0 + 396, y - 4, 28, 24, e) ? 1 : 0; if (!d) return; int v = z_cfg_get(EN[i].key, EN[i].def), k = 0; for (int j = 0; j < EN[i].nv; j++) if (EN[i].v[j] <= v) k = j; k = MAX(0, MIN(EN[i].nv - 1, k + d)); z_cfg_set(EN[i].key, EN[i].v[k]); z_notify(); return; }
    int y = 70 + NEN * 44; if (in(X0, y - 4, 400, 24, e)) { z_cfg_set("pin_al_volver", !z_cfg_get("pin_al_volver", 1)); z_notify(); return; }
    y += 44; if (in(X0, y - 6, 240, 30, e)) { z_cfg_set("salvapantallas_ya", 1); z_notify(); z_log("[prueba] salvapantallas pedido"); } }
/* ---------- Sistema ---------- */
static void d_sis(void) { hdr("Sistema"); zsys s; z_sysinfo(&s); ln("%s: %s", _("Procesador"), s.cpu); ln("%s: %lu MB (%lu MB %s)", _("Memoria"), s.mem_total >> 20, s.mem_free >> 20, _("libres")); ln("%s: %s", _("Arranque"), s.boot_mode == 2 ? "UEFI" : "BIOS"); Y += 6; g_textb(W, X0, Y, _("Discos"), UI_TEXT); Y += 20; zdisk d[16]; int n = z_disks(d, 16); for (int i = 0; i < n && i < 6; i++) ln("%-8s %6lu MB  %s", d[i].name, d[i].sectors * d[i].ssize >> 20, d[i].model); Y += 6; g_textb(W, X0, Y, _("Red"), UI_TEXT); Y += 20; znet ni; if (z_netinfo(&ni)) ln("%s", _("Ethernet: no hay tarjeta compatible.")); else { char a[16]; z_fmt_ip(ni.ip, a); ln("%s (%s)  %s  IP %s", ni.name, ni.kind, ni.up ? _("conectado") : _("sin cable"), a); } zpci pc[64]; int np = z_pci(pc, 64); for (int k = 0; k < np; k++) if (pc[k].cls == 2 && pc[k].sub == 0x80) ln(_("Wi-Fi %04x:%04x detectada: todavía sin driver"), pc[k].vendor, pc[k].device); Y += 6; g_textb(W, X0, Y, "PCI", UI_TEXT); Y += 20; for (int i = 0; i < np && Y < W->h - 20; i++) ln("%02x:%02x.%d  %04x:%04x  %02x.%02x", pc[i].bus, pc[i].dev, pc[i].fn, pc[i].vendor, pc[i].device, pc[i].cls, pc[i].sub); }
static void draw(void) { g_clear(W, UI_BG); g_rect(W, 0, 0, SW, W->h, UI_PANEL); g_textb(W, 14, 14, _("Configuración"), UI_TEXT); for (int i = 0; i < NSEC; i++) { int y = 44 + i * 32; if (i == sec) g_round(W, 6, y, SW - 12, 28, 4, UI_ACC); g_text(W, 16, y + 6, _(SN[i]), i == sec ? 0xFFFFFF : UI_TEXT); } switch (sec) { case 0: d_apar(); break; case 1: d_fondo(); break; case 2: d_fecha(); break; case 3: d_idioma(); break; case 4: d_mando(); break; case 5: d_prog(); break; case 6: d_pant(); break; case 8: d_ener(); break; default: d_sis(); } g_text(W, X0, W->h - 18, msg, UI_MUTED); zw_present(W); }
static void go(int s) { sec = s; msg[0] = 0; z_joy_raw = s == 4; if (s == 1) f_load(); if (s == 2) f_init(); if (s == 5) p_load(); }
int main(const char *a) { z_theme_get(&t); zsys s; z_sysinfo(&s); W = zw_new("Configuración", -1, 0, MIN(900, (int)s.scr_w - 40), MIN(560, (int)s.scr_h - 80), WF_DECOR | WF_RESIZE); static const char *AR[] = {"apariencia", "fondo", "fecha", "idioma", "mandos", "programas", "pantalla", "sistema", "energia"}; for (int i = 0; i < NSEC; i++) if (!strcmp(a, AR[i])) sec = i; go(sec); draw(); zevent e;
    for (;;) { int g = z_event(&e, 1000); if (!g) { if (sec == 2 || sec == 7) draw(); continue; } if (e.type == EV_REDRAW) { z_theme_get(&t); draw(); continue; } if (e.win != (u32)W->id && e.type != EV_JOY) continue; if (e.type == EV_CLOSE) return 0; if (e.type == EV_RESIZE) { zw_resized(W, e.x, e.y); draw(); continue; } if (e.type == EV_DOWN && e.x < SW) { int i = (e.y - 44) / 32; if (e.y >= 44 && i < NSEC) go(i); draw(); continue; } switch (sec) { case 0: k_apar(&e); break; case 1: k_fondo(&e); break; case 2: k_fecha(&e); break; case 3: k_idioma(&e); break; case 4: k_mando(&e); break; case 5: k_prog(&e); break; case 6: k_pant(&e); break; case 8: k_ener(&e); break; } draw(); }
}
